+  display:flex;flex-direction:column;gap:4px;
+  padding:12px 12px;border-radius:14px;border:1px solid rgba(10,22,40,.10);background:#fff;
+}
+.mega-links a:hover{border-color:rgba(199,162,74,.45);box-shadow:0 10px 24px rgba(10,22,40,.10)}
+.mega-links .title{font-weight:800;color:var(--navy)}
