+}
+.hero .container{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:end}
+.hero h1{color:#fff}
+.hero p{color:rgba(255,255,255,.84);font-size:18px}
+.hero-card{align-self:stretch;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);border-radius:18px;padding:18px;backdrop-filter: blur(10px)}
+.hero-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
+.metric{padding:14px;border-radius:16px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12)}
