+.cap .h strong{font-size:16px;color:var(--navy)}
+.cap p{color:rgba(10,22,40,.74);font-size:14px;margin-top:8px}
+.cap a{margin-top:12px;display:inline-flex;gap:8px;align-items:center;font-weight:800;color:var(--navy)}
+.arrow{width:10px;height:10px;border-right:2px solid var(--navy);border-bottom:2px solid var(--navy);transform:rotate(-45deg)}
+
+/* Partners carousel */
+.carousel{position:relative}
+.carousel-track{display:flex;gap:14px;overflow:hidden;scroll-behavior:smooth}
+.partner{min-width:320px;flex:0 0 auto}
+.carousel-controls{display:flex;gap:10px;margin-top:12px}
+.icon-btn{width:44px;height:44px;border-radius:14px;border:1px solid var(--line);background:#fff;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
+.icon-btn:hover{border-color:rgba(199,162,74,.45)}
+
+/* Footer */
+footer{background:var(--navy);color:#fff}
+.footer-top{display:grid;grid-template-columns:1.2fr 1fr;gap:24px;padding:52px 0 24px;border-bottom:1px solid rgba(255,255,255,.12)}
+.footer-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
+.footer-grid a{color:rgba(255,255,255,.82);padding:8px 0}
+.footer-grid a:hover{color:#fff}
+.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 0 28px;color:rgba(255,255,255,.68);font-size:13px}
+
+/* Forms */
+.field{display:flex;gap:10px}
+input[type="email"],input[type="text"]{
+  width:100%;padding:12px 14px;border-radius:999px;border:1px solid rgba(10,22,40,.18);
+  background:#fff;outline:none;
+}
+input[type="email"]:focus,input[type="text"]:focus{border-color:rgba(199,162,74,.65);box-shadow:0 0 0 4px rgba(199,162,74,.18)}
+
+/* Utility */
+.muted{color:rgba(10,22,40,.70)}
+.small{font-size:13px}
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero .container{grid-template-columns:1fr;gap:18px}
+  .two-col{grid-template-columns:1fr}
+  .three-col{grid-template-columns:1fr}
+  .four-col{grid-template-columns:1fr 1fr}
+  .tabs{grid-template-columns:1fr}
+  .tablist{border-right:0;border-bottom:1px solid rgba(10,22,40,.08)}
+  .cap-grid{grid-template-columns:1fr}
+}
+@media (max-width: 820px){
+  h1{font-size:36px}
+  h2{font-size:28px}
+  .nav{display:none}
+  .nav-actions .btn{display:none}
+  .nav-toggle{display:inline-flex}
+  .mobile-drawer.open{display:block}
+}
+@media (max-width: 520px){
+  .four-col{grid-template-columns:1fr}
+  .hero{min-height:560px}
+  .partner{min-width:280px}
+}
+
*** End Patch
PATCH

